function showToast(text){document.getElementById('toastText').textContent=text;const t=document.getElementById('toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function renderSchedule(){const html=schedule.map(a=>`<div class="appointment"><div class="time">${a.time}<small>${a.duration}</small></div><div class="apt-line" style="--apt:${a.color}"></div><div class="apt-info"><strong>${a.name}</strong><span>${a.care}</span></div><span class="status ${a.cls}">${a.status}</span></div>`).join('');document.getElementById('todaySchedule').innerHTML=html;document.getElementById('dayAgenda').innerHTML=schedule.map(a=>`<div class="day-apt"><i class="dot" style="--apt:${a.color}"></i><div><strong>${a.time} · ${a.name}</strong><span>${a.care} · ${a.duration}</span></div></div>`).join('')}
function renderActivity(){const actor=role==='dentiste'?'Dr Charki':'Hanane';document.getElementById('activityList').innerHTML=`<div class="mini-item"><span class="mini-icon">${icons.check}</span><div><strong>Paiement de 800 MAD enregistré</strong><span>Sara El Mansouri · par Hanane</span></div><time>14:24</time></div><div class="mini-item"><span class="mini-icon">${icons.calendar}</span><div><strong>Rendez-vous confirmé</strong><span>Omar Lahlou · par ${actor}</span></div><time>13:06</time></div><div class="mini-item"><span class="mini-icon">${icons.file}</span><div><strong>Plan de traitement mis à jour</strong><span>Karim Alaoui · par Dr Charki</span></div><time>10:42</time></div>`}
function renderPatients(){const q=(document.getElementById('patientSearch')?.value||'').toLowerCase();const filter=document.getElementById('patientFilter')?.value||'all';const list=patients.filter(p=>(p.name.toLowerCase().includes(q)||p.phone.includes(q)||p.id.toLowerCase().includes(q))&&(filter!=='balance'||p.balance>0)&&(filter!=='upcoming'||p.next!=='—'));document.getElementById('patientsBody').innerHTML=list.map(p=>`<tr><td><div class="patient-cell"><span class="avatar">${p.initials}</span><span><strong>${p.name}</strong><span>#${p.id}</span></span></div></td><td>${p.phone}</td><td class="muted">${p.last}</td><td>${p.next}</td><td class="amount">${formatMAD(p.balance)}</td><td><button class="row-actions" data-open-patient="${p.id}">•••</button></td></tr>`).join('');document.getElementById('patientsEmpty').classList.toggle('hidden',list.length>0);document.getElementById('patientsCount').textContent=(120+patients.length)+' patients enregistrés';document.querySelectorAll('[data-open-patient]').forEach(b=>b.onclick=()=>{navigate('dossier');showToast('Dossier patient ouvert')})}
function renderPayments(){document.getElementById('paymentsBody').innerHTML=payments.map(p=>`<tr><td class="muted">${p.ref}</td><td><strong>${p.name}</strong></td><td>${p.date}</td><td>${p.mode}</td><td class="amount">${p.amount}</td><td><span class="status">Encaissé</span></td></tr>`).join('')}
function renderTreatments(){const rows=[['SE','Sara El Mansouri','#PAT-00281','Couronne + endodontie','2 soins sur 4','4 800 MAD','2 200 MAD','En cours'],['KA','Karim Alaoui','#PAT-00274','Implant unitaire','1 soin sur 5','9 500 MAD','7 000 MAD','En cours'],['LI','Lina Idrissi','#PAT-00268','Soins conservateurs','3 soins sur 3','1 650 MAD','0 MAD','Terminé'],['YO','Youssef Ouazzani','#PAT-00255','Prothèse partielle','2 soins sur 6','6 200 MAD','4 200 MAD','En cours']];document.getElementById('treatmentsBody').innerHTML=rows.map(r=>`<tr><td><div class="patient-cell"><span class="avatar">${r[0]}</span><span><strong>${r[1]}</strong><span>${r[2]}</span></span></div></td><td>${r[3]}</td><td>${r[4]}</td><td class="amount">${r[5]}</td><td class="amount">${r[6]}</td><td><span class="status ${r[7]==='En cours'?'wait':''}">${r[7]}</span></td></tr>`).join('')}
function renderCalendar(){const days=['Lun. 7','Mar. 8','Mer. 9','Jeu. 10','Ven. 11'];let html='<div class="cal-head"></div>'+days.map(d=>`<div class="cal-head"><div>${d.split(' ')[0]}<b>${d.split(' ')[1]}</b></div></div>`).join('');const events={41:'Contrôle',48:'Endodontie',50:'Consultation',57:'Détartrage',69:'Couronne',71:'Implant',78:'Urgence'};for(let hour=8;hour<17;hour++){html+=`<div class="cal-time">${String(hour).padStart(2,'0')}:00</div>`;for(let d=0;d<5;d++){const val=events[hour*5+d];html+=`<div class="cal-cell">${val?`<div class="cal-event ${d===3?'orange':d===4?'blue':''}">${val}<br>${hour}:00</div>`:''}</div>`}}document.getElementById('calendarGrid').innerHTML=html}
function renderReport(){const values=[['Avr.','48 200','56%'],['Mai','58 600','68%'],['Juin','53 400','62%'],['Juil.','67 200','78%'],['Août','64 400','75%'],['Sept.','72 400','88%']];document.getElementById('barChart').innerHTML=values.map(v=>`<div class="bar-col"><div class="bar" style="--h:${v[2]}" data-value="${v[1]}"></div><span>${v[0]}</span></div>`).join('')}

function renderPatientTab(tab='resume'){
 const c=document.getElementById('patientTabContent');
 if(role!=='dentiste'&&['odontogramme','traitement','documents'].includes(tab)){c.innerHTML=`<article class="card access-lock"><div class="lock-icon">${icons.lock}</div><h3>Accès clinique réservé</h3><p>Les informations médicales, diagnostics et documents cliniques sont accessibles uniquement à Dr Charki Meryem.</p></article>`;return}
 if(tab==='odontogramme'){const teeth=['18','17','16','15','14','13','12','11','21','22','23','24','25','26','27','28','48','47','46','45','44','43','42','41','31','32','33','34','35','36','37','38'];c.innerHTML=`<article class="card odonto"><div class="card-head"><div><h3>Odontogramme adulte</h3><p>Cliquez sur une dent pour consulter ou modifier son état</p></div><button class="btn btn-soft">Ajouter un acte</button></div><div class="teeth-row">${teeth.slice(0,16).map(t=>`<button class="tooth ${t==='14'?'flagged':t==='16'?'done':''}" data-tooth="${t}">${t}</button>`).join('')}</div><div class="teeth-row">${teeth.slice(16).map(t=>`<button class="tooth ${t==='36'?'done':''}" data-tooth="${t}">${t}</button>`).join('')}</div><div class="odont-legend"><span><i class="legend-dot"></i>Sain</span><span><i class="legend-dot plan"></i>Planifié</span><span><i class="legend-dot complete"></i>Traité</span></div></article>`;c.querySelectorAll('[data-tooth]').forEach(b=>b.onclick=()=>showToast(`Dent ${b.dataset.tooth} sélectionnée`));return}
 if(tab==='traitement'){c.innerHTML=`<div class="grid patient-grid"><article class="card info-card"><h3>Plan actif · Couronne & endodontie</h3><div class="treatment-list"><div class="treatment"><strong>Endodontie · dent 14</strong><span>Planifié le 10 sept. 2026</span><b>1 800 MAD</b></div><div class="treatment"><strong>Reconstitution coronaire</strong><span>À planifier</span><b>700 MAD</b></div><div class="treatment"><strong>Couronne céramo-céramique</strong><span>À planifier</span><b>2 300 MAD</b></div></div></article><article class="card info-card"><h3>Résumé du devis</h3><div class="info-grid"><div class="info"><label>Montant total</label><span>4 800 MAD</span></div><div class="info"><label>Déjà réglé</label><span>2 600 MAD</span></div><div class="info"><label>Reste à payer</label><span>2 200 MAD</span></div><div class="info"><label>Progression</label><span>2 actes sur 4</span></div></div></article></div>`;return}
 if(tab==='paiements-patient'){c.innerHTML=`<article class="card table-card"><table class="data-table"><thead><tr><th>Date</th><th>Libellé</th><th>Mode</th><th>Montant</th><th>Statut</th></tr></thead><tbody><tr><td>12 sept. 2026</td><td>Acompte endodontie</td><td>Carte bancaire</td><td class="amount">800 MAD</td><td><span class="status">Encaissé</span></td></tr><tr><td>10 sept. 2026</td><td>Consultation & radiographie</td><td>Espèces</td><td class="amount">500 MAD</td><td><span class="status">Encaissé</span></td></tr></tbody></table></article>`;return}
 if(tab==='documents'){c.innerHTML=`<article class="card info-card"><h3>Documents du patient</h3><div class="mini-item"><span class="mini-icon">${icons.file}</span><div><strong>Radiographie panoramique</strong><span>PDF · 10 septembre 2026</span></div><button class="btn btn-outline">Consulter</button></div><div class="mini-item"><span class="mini-icon">${icons.file}</span><div><strong>Consentement aux soins</strong><span>PDF · 10 septembre 2026</span></div><button class="btn btn-outline">Consulter</button></div></article>`;return}
 c.innerHTML=`<div class="grid patient-grid"><div class="grid"><article class="card info-card"><h3>Informations générales</h3><div class="info-grid"><div class="info"><label>Date de naissance</label><span>17 mars 1995</span></div><div class="info"><label>Téléphone</label><span>06 12 34 56 78</span></div><div class="info"><label>Adresse</label><span>Maarif, Casablanca</span></div><div class="info"><label>Mutuelle</label><span>CNSS</span></div></div></article>${role==='dentiste'?`<article class="card info-card"><h3>Informations médicales</h3><div class="alert">${icons.alert}<span><b>Allergie signalée :</b> pénicilline. Vérifier avant toute prescription.</span></div><div class="info-grid"><div class="info"><label>Antécédents</label><span>Aucun antécédent majeur</span></div><div class="info"><label>Traitement en cours</label><span>Aucun</span></div></div></article>`:''}</div><article class="card info-card"><h3>Historique récent</h3><div class="timeline"><div class="timeline-item"><time>10 septembre 2026</time><strong>Consultation & radiographie</strong><p>Diagnostic dent 14 et création du plan.</p></div><div class="timeline-item"><time>2 juillet 2026</time><strong>Détartrage complet</strong><p>Acte terminé sans complication.</p></div><div class="timeline-item"><time>18 mars 2026</time><strong>Contrôle périodique</strong><p>Conseils d’hygiène bucco-dentaire.</p></div></div></article></div>`
}

function applyRole(){const dentist=role==='dentiste';document.getElementById('sideAvatar').textContent=dentist?'MC':'HA';document.getElementById('sideAvatar').className='avatar'+(dentist?'':' assistante');document.getElementById('sideName').textContent=dentist?'Dr Charki Meryem':'Hanane';document.getElementById('sideRole').textContent=dentist?'Dentiste':'Assistante';document.getElementById('welcomeTitle').textContent=dentist?'Bonjour, Dr Charki':'Bonjour, Hanane';document.querySelectorAll('.dentist-only,.clinical-nav').forEach(x=>x.classList.toggle('hidden',!dentist));renderActivity();renderPatientTab()}
function login(selected){role=selected;localStorage.setItem('cabinetRole',role);document.getElementById('login').classList.add('hidden');document.getElementById('app').classList.remove('hidden');applyRole();navigate('dashboard')}
function logout(){role='';localStorage.removeItem('cabinetRole');document.getElementById('app').classList.add('hidden');document.getElementById('login').classList.remove('hidden')}
function navigate(page){if(role!=='dentiste'&&['dossier','traitements','rapports'].includes(page))page='dashboard';document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));document.getElementById('page-'+page)?.classList.add('active');document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelectorAll('.mobile-nav-btn[data-mobile-page]').forEach(b=>b.classList.toggle('active',b.dataset.mobilePage===page));const titles={dashboard:'Tableau de bord',agenda:'Agenda',patients:'Patients',dossier:'Dossier clinique',traitements:'Plans de traitement',paiements:'Paiements',rapports:'Rapports',parametres:'Paramètres'};document.getElementById('headerTitle').textContent=titles[page]||'Cabinet';document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(page==='patients')renderPatients();if(page==='dossier')renderPatientTab()}

